import React from "react";
import { Container } from "react-bootstrap";
import { Header, ExperienceCard } from "../../components";
import usePortfolioData from "../../hooks/usePortfolioData";
import styles from "./Experience.module.css";

// @@ AI-COMMENT: Experience page component with warm neutral grid design
const Experience = () => {
  const { experience: experienceData, loading } = usePortfolioData();
  const colorSequence = ["yellow", "purple", "cyan"];

  if (loading) return null;

  return (
    <div className={styles.container}>
      <header className={styles.headerContainer}>
        <h1 className={styles.headerTitle}>Experience</h1>
      </header>

      <div className={styles.experienceGrid}>
        {experienceData.map((obj, index) => {
          const colorVariant = colorSequence[index % colorSequence.length];
          return (
            <ExperienceCard
              key={index}
              title={obj.title}
              organization={obj.organization}
              liveUrl={obj.liveUrl}
              duration={obj.duration}
              description={obj.description}
              logo={obj.logo}
              techStack={obj.techStack}
              colorVariant={colorVariant}
            />
          );
        })}
      </div>
    </div>
  );
};

export default Experience;
