import projectsData from "../data/Projects.json";
import experienceData from "../data/Experience.json";
import techStackData from "../data/TechStack.json";
import involvementsData from "../data/Involvements.json";
import achievementsData from "../data/Achievements.json";

/**
 * PortfolioService
 * Centralizes data access for the portfolio.
 * Follows SOLID principles by decoupling data sources from UI components.
 */
const PortfolioService = {
    getProjects: () => {
        return projectsData;
    },

    getExperience: () => {
        return experienceData;
    },

    getTechStack: () => {
        return techStackData;
    },

    getInvolvements: () => {
        return involvementsData;
    },

    getAchievements: () => {
        return achievementsData;
    },

    /**
     * Example of an advanced feature: Filter projects by tech stack.
     * Demonstrates the power of a centralized service.
     */
    getProjectsByTech: (tech) => {
        return projectsData.filter((project) =>
            project.techStack.some((item) => item.toLowerCase() === tech.toLowerCase())
        );
    },
};

export default PortfolioService;
